use futures_util::{SinkExt,StreamExt};use serde_json::json;use tokio_tungstenite::{connect_async,tungstenite::Message};
#[tokio::main]async fn main(){let(mut b,_)=connect_async("wss://fstream.binance.com/stream?streams=btcusdt@bookTicker/ethusdt@bookTicker/solusdt@bookTicker").await.unwrap();let mut n=0;while n<100{if let Some(Ok(Message::Text(s)))=b.next().await{println!("{}",json!({"venue":"binance","raw":s}));n+=1}}
let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();o.send(Message::Text(r#"{"op":"subscribe","args":[{"channel":"books5","instId":"BTC-USDT"},{"channel":"books5","instId":"ETH-USDT"},{"channel":"books5","instId":"SOL-USDT"}]}"#.into())).await.unwrap();n=0;while n<100{if let Some(Ok(Message::Text(s)))=o.next().await{if !s.contains("\"event\""){println!("{}",json!({"venue":"okx","raw":s}));n+=1}}}}